body.script:
//
(function(){
var P=['position:static','top:auto','left:auto','right:auto','bottom:auto','margin:0','transform:none','float:none'];
function nav(){return document.querySelector('.pf-nav');}
function wrap(){
var n=nav();if(!n)return null;
var w=n.querySelector('.gtranslate_wrapper');
if(!w){w=document.createElement('div');w.className='gtranslate_wrapper';var b=n.querySelector('.pf-nav-search');n.insertBefore(w,b||null);}
return w;}
function place(){
var w=wrap();if(!w)return;
var f=document.querySelector('.gt_switcher_wrapper');
if(f&&f.parentNode!==w){w.appendChild(f);}
if(f){P.forEach(function(s){var k=s.split(':');f.style.setProperty(k[0],k[1],'important');});}
if(!w.dataset.b&&w.querySelector('.gt_selected')){w.dataset.b=1;
function pos(){var o=w.querySelector('.gt_option');if(!o)return;var r=w.getBoundingClientRect();var wd=Math.min(170,window.innerWidth-16);var l=Math.max(8,Math.min(r.right-wd,window.innerWidth-wd-8));
o.style.setProperty('top',(r.bottom+4)+'px','important');o.style.setProperty('left',l+'px','important');o.style.setProperty('right','auto','important');o.style.setProperty('width',wd+'px','important');}
w.addEventListener('click',function(){pos();setTimeout(pos,0);setTimeout(pos,80);},true);
window.addEventListener('scroll',pos,{passive:true});window.addEventListener('resize',pos);
}}
var n=0,t=setInterval(function(){place();if(++n>60)clearInterval(t);},250);
document.addEventListener('DOMContentLoaded',place);
window.addEventListener('load',place);
})();
//
